param([string]$ProjectRoot = (Split-Path -Parent $PSScriptRoot))
$ErrorActionPreference = 'Stop'
Add-Type -AssemblyName System.Drawing

# Technical size export only; composition and backgrounds are generated by ImageGen.
$names = @('welcome_phone', 'listing_under_review', 'no_connection', 'listing_unavailable', 'add_listing_photos')
foreach ($name in $names) {
    $source = [Drawing.Image]::FromFile((Join-Path $ProjectRoot "design/source/illustrations/$name.png"))
    $bitmap = New-Object Drawing.Bitmap(1024, 1024, ([Drawing.Imaging.PixelFormat]::Format24bppRgb))
    $graphics = [Drawing.Graphics]::FromImage($bitmap)
    try {
        $graphics.Clear([Drawing.Color]::FromArgb(250, 246, 241))
        $graphics.InterpolationMode = [Drawing.Drawing2D.InterpolationMode]::HighQualityBicubic
        $graphics.PixelOffsetMode = [Drawing.Drawing2D.PixelOffsetMode]::HighQuality
        $graphics.DrawImage($source, 0, 0, 1024, 1024)
        $bitmap.Save((Join-Path $ProjectRoot "assets/illustrations/$name.png"), [Drawing.Imaging.ImageFormat]::Png)
    } finally {
        $graphics.Dispose()
        $bitmap.Dispose()
        $source.Dispose()
    }
}
